def gen(rng):
    def make(n, style):
        val = [rng.randint(-1000, 1000)]
        L, R = [-1], [-1]
        free = [(0, 0), (0, 1)]
        for _ in range(n - 1):
            if style == 'random':
                k = rng.randrange(len(free))
                free[k], free[-1] = free[-1], free[k]
                u, s = free.pop()
            elif style == 'chain':
                u, s = free.pop() if rng.random() < 0.9 else free.pop(0)
            else:  # balanced: fill breadth first
                u, s = free.pop(0)
            val.append(rng.randint(-1000, 1000))
            L.append(-1)
            R.append(-1)
            v = len(val) - 1
            if s == 0:
                L[u] = v
            else:
                R[u] = v
            free.append((v, 0))
            free.append((v, 1))
        return val, L, R
    def level(val, L, R):
        out = []
        q = [0]
        h = 0
        while h < len(q):
            u = q[h]
            h += 1
            if u == -1:
                out.append('null')
            else:
                out.append(str(val[u]))
                q.append(L[u])
                q.append(R[u])
        while out and out[-1] == 'null':
            out.pop()
        return out
    def pre(val, L, R):
        out = []
        st = [0]
        while st:
            u = st.pop()
            if u == -1:
                out.append('null')
            else:
                out.append(str(val[u]))
                st.append(R[u])
                st.append(L[u])
        return out
    def S(n, style):
        return 'S\n' + ' '.join(level(*make(n, style)))
    def D(n, style):
        return 'D\n' + ' '.join(pre(*make(n, style)))
